import{_ as a,c as t,o,ag as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"簡介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1791311600000}'),d={name:"zh-TW/guide/introduction.md"};function i(l,e,n,c,h,s){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to &quot;簡介&quot;">​</a></h1><h2 id="關於-nplyr" tabindex="-1">關於 nPlyr <a class="header-anchor" href="#關於-nplyr" aria-label="Permalink to &quot;關於 nPlyr&quot;">​</a></h2><p><strong>nPlyr</strong> 是一款面向 <strong>macOS</strong> 與 <strong>iOS / iPadOS</strong> 的原生影片播放器。它建構於 Apple 的 <a href="https://developer.apple.com/av-foundation/" target="_blank" rel="noreferrer">AVFoundation</a>（<code>AVPlayer</code>）之上——應用程式內部<strong>沒有任何外部二進位</strong>。在播放器的基礎之上，它還加入了兩項讓它超越普通播放器的能力：</p><ul><li>一個<strong>內建媒體嗅探器</strong>（Chrome 風格的多分頁瀏覽器，可從任意網頁擷取影片直鏈），以及</li><li>一個 <strong>hikerView 相容的小程式執行環境</strong>，執行社群規則，讓應用程式能夠瀏覽並解析第三方影片來源。</li></ul><p>這個組合有時被稱為集「播放器 + 嗅探器 + 小程式執行環境」於一身。</p><h2 id="三大支柱" tabindex="-1">三大支柱 <a class="header-anchor" href="#三大支柱" aria-label="Permalink to &quot;三大支柱&quot;">​</a></h2><h3 id="_1-原生播放器" tabindex="-1">1. 原生播放器 <a class="header-anchor" href="#_1-原生播放器" aria-label="Permalink to &quot;1. 原生播放器&quot;">​</a></h3><p>macOS 與 iOS 共用一套播放核心。它能播放 HLS（<code>m3u8</code>）、<code>MP4</code>、<code>MOV</code>、<code>M4V</code>、<code>FLV</code>、<code>TS</code> 以及任何 <code>AVPlayer</code> 可解碼的容器，並支援：</p><ul><li>字幕（外部 <code>.srt</code> / <code>.vtt</code> / 內嵌）</li><li>多音軌</li><li>倍速控制</li><li>畫中畫</li><li>AirPlay，以及（macOS 上）DLNA 投放</li></ul><p>請參閱 <a href="/zh-TW/guide/player.html">播放器</a>。</p><h3 id="_2-嗅探瀏覽器" tabindex="-1">2. 嗅探瀏覽器 <a class="header-anchor" href="#_2-嗅探瀏覽器" aria-label="Permalink to &quot;2. 嗅探瀏覽器&quot;">​</a></h3><p>nPlyr 內建一個真正的 <code>WKWebView</code>，擁有多個 Chrome 風格的分頁。每個頁面都會被注入媒體偵測腳本；當頁面請求 <code>m3u8</code> / <code>mp4</code> / <code>flv</code> / <code>ts</code> 媒體時，該連結與其請求標頭會一併出現在結果抽屜中，你可以直接傳送給播放器或下載器。</p><p>請參閱 <a href="/zh-TW/guide/browser.html">瀏覽器與嗅探器</a>。</p><h3 id="_3-小程式執行環境" tabindex="-1">3. 小程式執行環境 <a class="header-anchor" href="#_3-小程式執行環境" aria-label="Permalink to &quot;3. 小程式執行環境&quot;">​</a></h3><p>nPlyr 原生重新實作了 <strong>hikerView 小程式契約</strong>：</p><ul><li>規則 DSL（<code>pdfh</code> / <code>pdfa</code> / <code>pd</code> 選擇器、<code>setResult</code>、<code>lazyRule</code>、<code>$.rule</code> 等），</li><li>規則用於呼叫宿主功能的 <code>fy_bridge_app</code>（<code>fba</code>）JavaScript 橋（播放、fetch、解析、儲存變數），</li><li><code>hiker://</code> 偽協定路由。</li></ul><p>因此，現有的 hikerView 社群規則與小程式可以直接在 nPlyr 中執行。由於原始引擎是 Android/Java（Rhino），<strong>部分 Java 特有的行為未能完全相容</strong>——這一點在<a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>頁面中有詳細說明。</p><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>最低版本</th><th>說明</th></tr></thead><tbody><tr><td>macOS</td><td>macOS 14 Sonoma</td><td>針對 Apple Silicon（M 系列）最佳化；支援 Intel</td></tr><tr><td>iOS</td><td>iOS 16</td><td>iPhone</td></tr><tr><td>iPadOS</td><td>iPadOS 16</td><td>iPad</td></tr></tbody></table><ul><li><strong>記憶體</strong>：最低 4 GB RAM，大型 HLS 播放清單建議 8 GB。</li><li><strong>儲存空間</strong>：安裝約需 60 MB，外加下載媒體所佔空間。</li><li><strong>網路</strong>：串流媒體、嗅探與小程式來源均需要網路。</li></ul><h2 id="支援的語言" tabindex="-1">支援的語言 <a class="header-anchor" href="#支援的語言" aria-label="Permalink to &quot;支援的語言&quot;">​</a></h2><p>應用程式介面已翻譯為 <strong>25 種語言</strong>，並在首次啟動時跟隨系統語言。本文檔站點提供英文、簡體中文、繁體中文、日本語、Deutsch、Español 與 Français。</p><h2 id="快速開始" tabindex="-1">快速開始 <a class="header-anchor" href="#快速開始" aria-label="Permalink to &quot;快速開始&quot;">​</a></h2><ol><li>在你的 Mac 或 iPhone 上<a href="/zh-TW/guide/installation.html">安裝</a> nPlyr。</li><li>了解<a href="/zh-TW/guide/player.html">播放器</a>基礎。</li><li>使用<a href="/zh-TW/guide/browser.html">瀏覽器與嗅探器</a>擷取影片串流。</li><li>透過<a href="/zh-TW/guide/miniapps.html">小程式</a>探索社群資源。</li></ol>',24)])])}const m=a(d,[["render",i]]);export{u as __pageData,m as default};
